import type { ControlUiSkin } from "@/components/control-ui/skin";

export const skin: ControlUiSkin = {
  id: "refined",
  sidebarLayout: "page",
  indicators: {
    sidebar: "hover",
    "button-group": "hover",
    "toggle-group": "hover",
    "checkbox-group": "hover",
  },
};

[data-skin="refined"],
[data-skin="refined"] :where([data-control-family]) {
  --refined-button-radius: calc(var(--radius-control) * 2);
  --refined-surface-shadow:
    0 0 0 var(--control-rim-width) oklch(from var(--shadow-color) l c h / calc(0.06 * var(--ring-opacity))),
    0 calc(1px * var(--shadow-size)) calc(2px * var(--shadow-size)) calc(-1px * var(--shadow-size))
    oklch(from var(--shadow-color) l c h / calc(0.06 * var(--shadow-opacity))),
    0 calc(2px * var(--shadow-size)) calc(4px * var(--shadow-size))
    oklch(from var(--shadow-color) l c h / calc(0.04 * var(--shadow-opacity)));
  --refined-floating-shadow:
    0 0 0 var(--control-rim-width) oklch(from var(--shadow-color) l c h / calc(0.07 * var(--ring-opacity))),
    0 calc(1px * var(--shadow-size)) calc(2px * var(--shadow-size))
    oklch(from var(--shadow-color) l c h / calc(0.02 * var(--shadow-opacity))),
    0 calc(4px * var(--shadow-size)) calc(16px * var(--shadow-size))
    oklch(from var(--shadow-color) l c h / calc(0.025 * var(--shadow-opacity))),
    0 calc(16px * var(--shadow-size)) calc(56px * var(--shadow-size))
    oklch(from var(--shadow-color) l c h / calc(0.05 * var(--shadow-opacity)));
}

:is(.dark [data-skin="refined"], [data-skin="refined"].dark),
:is(.dark [data-skin="refined"], [data-skin="refined"].dark) :where([data-control-family]) {
  --refined-surface-shadow:
    inset 0 calc(1px * min(var(--shadow-size), 1))
    oklch(from var(--shadow-highlight) l c h / calc(alpha * var(--shadow-opacity))),
    inset 0 0 0 var(--control-rim-width)
    oklch(from var(--shadow-highlight) l c h / calc(alpha * var(--ring-opacity))),
    0 0 0 var(--control-rim-width) oklch(from var(--shadow-color) l c h / calc(0.1 * var(--ring-opacity))),
    0 calc(2px * var(--shadow-size)) calc(2px * var(--shadow-size))
    oklch(from var(--shadow-color) l c h / calc(0.1 * var(--shadow-opacity))),
    0 calc(4px * var(--shadow-size)) calc(4px * var(--shadow-size))
    oklch(from var(--shadow-color) l c h / calc(0.1 * var(--shadow-opacity))),
    0 calc(8px * var(--shadow-size)) calc(8px * var(--shadow-size))
    oklch(from var(--shadow-color) l c h / calc(0.1 * var(--shadow-opacity)));
  --refined-floating-shadow:
    inset 0 calc(1px * min(var(--shadow-size), 1))
    oklch(from var(--shadow-highlight) l c h / calc(alpha * var(--shadow-opacity))),
    inset 0 0 0 var(--control-rim-width)
    oklch(from var(--shadow-highlight) l c h / calc(alpha * 2 * var(--ring-opacity))),
    0 0 0 var(--control-rim-width) oklch(from var(--shadow-color) l c h / calc(0.4 * var(--ring-opacity))),
    0 calc(6px * var(--shadow-size)) calc(16px * var(--shadow-size)) calc(-4px * var(--shadow-size))
    oklch(from var(--shadow-color) l c h / calc(0.3 * var(--shadow-opacity))),
    0 calc(16px * var(--shadow-size)) calc(48px * var(--shadow-size)) calc(-8px * var(--shadow-size))
    oklch(from var(--shadow-color) l c h / calc(0.5 * var(--shadow-opacity)));
}

@layer base {
  [data-skin="refined"],
  :root[data-skin="refined"] body {
    letter-spacing: normal;
    -webkit-font-smoothing: antialiased;
  }
}

@layer components {
  [data-skin="refined"] :where([data-control-family="button"][data-control="true"]:not([data-shape="circle"])) {
    --cui-button-radius: var(--refined-button-radius);
  }

  [data-skin="refined"] :where([data-control-family="button-group"][data-slot="root"]) {
    --cui-button-group-text-radius: var(--refined-button-radius);
  }

  [data-skin="refined"]
    :where([data-track]:has(> [data-control-family="button"][data-track-item]) > [data-control-family="track-highlight"]) {
    --cui-track-highlight-radius: var(--refined-button-radius);
  }

  [data-skin="refined"] :where([data-control-family="button"][data-control="true"]) {
    --cui-button-gap: calc(var(--spacing) * 1.25);
    --cui-button-icon: 0.875rem;
    --cui-button-press-scale: 0.97;
  }

  [data-skin="refined"] :where([data-control-family="button"][data-size="xs"]) {
    --cui-button-gap: var(--spacing);
    --cui-button-icon: 0.75rem;
    --cui-button-padding-inline: calc(var(--padding-x) * 5 / 6);
    --cui-button-icon-padding-inline: max(0px, calc(var(--cui-button-padding-inline) - var(--spacing)));
  }

  [data-skin="refined"] :where([data-control-family="button"][data-size="sm"]) {
    --cui-button-font-size: var(--text-body);
    --cui-button-padding-inline: var(--padding-x);
    --cui-button-icon-padding-inline: max(0px, calc(var(--cui-button-padding-inline) - var(--spacing) * 0.75));
  }

  [data-skin="refined"] :where([data-control-family="button"][data-size="lg"]) {
    --cui-button-gap: calc(var(--spacing) * 1.5);
    --cui-button-padding-inline: calc(var(--padding-x) * 7 / 6);
  }

  [data-skin="refined"] :where([data-control-family="button"][data-variant="solid"]) {
    --cui-button-shadow:
      0 0 0 var(--control-rim-width) oklch(from var(--shadow-color) l c h / calc(0.6 * var(--ring-opacity))),
      0 calc(1px * var(--shadow-size)) calc(2px * var(--shadow-size)) calc(-1px * var(--shadow-size))
      oklch(from var(--shadow-color) l c h / calc(0.4 * var(--shadow-opacity))),
      0 calc(2px * var(--shadow-size)) calc(4px * var(--shadow-size))
      oklch(from var(--shadow-color) l c h / calc(0.18 * var(--shadow-opacity)));
  }

  [data-skin="refined"] :where([data-control-family="button"][data-variant="surface"]) {
    --cui-button-hover-background: var(--muted);
    --cui-button-shadow: var(--refined-surface-shadow);
  }

  [data-skin="refined"] :where([data-control-family="button"][data-tone="danger"][data-variant="solid"]) {
    --cui-button-shadow:
      0 0 0 var(--control-rim-width) oklch(from var(--destructive) l c h / calc(0.25 * var(--ring-opacity))),
      0 calc(1px * var(--shadow-size)) calc(2px * var(--shadow-size)) calc(-1px * var(--shadow-size))
      oklch(from var(--destructive) l c h / calc(0.18 * var(--shadow-opacity))),
      0 calc(2px * var(--shadow-size)) calc(4px * var(--shadow-size))
      oklch(from var(--destructive) l c h / calc(0.12 * var(--shadow-opacity)));
  }

  [data-skin="refined"] :where([data-control-family="card"][data-slot="root"]) {
    --cui-card-radius: var(--radius-panel);
    --cui-card-border-width: 0px;
    --cui-card-shadow: var(--refined-surface-shadow);
  }

  [data-skin="refined"]
    :where(
      [data-control-family="popup"][data-popup-part="surface"],
      [data-control-family="popup"][data-popup-part="list-surface"],
      [data-control-family="popup"][data-popup-part="bar"]
    ) {
    --cui-popup-border-width: 0px;
    --cui-popup-shadow: var(--refined-surface-shadow);
  }

  [data-skin="refined"]
    :where(
      [data-control-family="popup"][data-popup-part="surface"]:not([data-popup-kind="tooltip"]),
      [data-control-family="popup"][data-popup-part="list-surface"]
    ) {
    --cui-popup-shadow: var(--refined-floating-shadow);
  }

  [data-skin="refined"] :where([data-control-family="popup"][data-popup-part="surface"]:is([data-popup-kind="drawer"], [data-popup-kind="sheet"])) {
    --cui-popup-shadow: var(--refined-surface-shadow), var(--shadow-overlay);
  }

  [data-skin="refined"] :where([data-control-family="field"][data-control="true"]) {
    --cui-field-radius: var(--radius-field);
    --cui-field-border-color: var(--input);
    --cui-field-border-width: 0px;
    --cui-field-focus-border-color: var(--focus-ring);
    --cui-field-shadow: var(--refined-surface-shadow);
  }

  [data-skin="refined"] :where([data-control-family="code"][data-slot="root"]) {
    --cui-code-background: var(--card);
    --cui-code-border-width: 0px;
    --cui-code-shadow: var(--refined-surface-shadow);
  }

  [data-skin="refined"] :where([data-control-family="tabs"][data-slot="root"]) {
    --cui-tabs-trigger-radius: var(--radius-field);
    --cui-tabs-list-padding: calc(var(--spacing) * 0.75);
    --cui-tabs-list-background: var(--muted);
    --cui-tabs-list-shadow: none;
    --cui-tabs-indicator-shadow: var(--refined-surface-shadow);
  }

  [data-skin="refined"] :where([data-control-family="range"][data-range-kind="slider"][data-slot="root"][data-variant="default"]) {
    --cui-range-indicator-background: oklch(from var(--muted-foreground) l c h / 0.5);
    --cui-range-thumb-background: var(--primary);
    --cui-range-thumb-border-color: var(--primary);
    --cui-range-thumb-shadow: var(--shadow-xs);
  }

  [data-skin="refined"] :where([data-control-family="switch"][data-slot="root"]) {
    --cui-switch-thumb-shadow: var(--refined-surface-shadow);
  }

  [data-skin="refined"] :where([data-control-family="table-of-contents"][data-slot="root"]) {
    --cui-table-of-contents-background: transparent;
    --cui-table-of-contents-border-width: 0px;
    --cui-table-of-contents-shadow: none;
    --cui-table-of-contents-padding: 0px;
    --cui-table-of-contents-item-font-size: var(--text-caption);
  }

  [data-skin="refined"] :where([data-control-family="sidebar"][data-slot="wrapper"]) {
    --cui-sidebar-inset-shadow: none;
  }

  :is(.dark [data-skin="refined"], [data-skin="refined"].dark) :where([data-control-family="button"][data-variant="solid"]) {
    --cui-button-shadow:
      inset 0 calc(1px * min(var(--shadow-size), 1)) oklch(1 0 0 / calc(0.45 * var(--shadow-opacity))),
      0 0 0 var(--control-rim-width) oklch(1 0 0 / calc(0.55 * var(--ring-opacity))),
      0 calc(1px * var(--shadow-size)) calc(2px * var(--shadow-size))
      oklch(from var(--shadow-color) l c h / calc(0.5 * var(--shadow-opacity)));
  }

  :is(.dark [data-skin="refined"], [data-skin="refined"].dark) :where([data-control-family="button"][data-variant="surface"]) {
    --cui-button-shadow:
      inset 0 calc(1px * min(var(--shadow-size), 1)) oklch(1 0 0 / calc(0.05 * var(--shadow-opacity))),
      inset 0 0 0 var(--control-rim-width) oklch(1 0 0 / calc(0.045 * var(--ring-opacity))),
      0 0 0 var(--control-rim-width) oklch(from var(--shadow-color) l c h / calc(0.14 * var(--ring-opacity))),
      0 calc(1px * var(--shadow-size)) calc(2px * var(--shadow-size)) calc(-1px * var(--shadow-size))
      oklch(from var(--shadow-color) l c h / calc(0.14 * var(--shadow-opacity))),
      0 calc(2px * var(--shadow-size)) calc(4px * var(--shadow-size))
      oklch(from var(--shadow-color) l c h / calc(0.08 * var(--shadow-opacity)));
  }

  :is(.dark [data-skin="refined"], [data-skin="refined"].dark)
    :where([data-control-family="button"][data-tone="danger"][data-variant="solid"]) {
    --cui-button-shadow:
      inset 0 calc(1px * min(var(--shadow-size), 1)) oklch(from var(--destructive) l c h / calc(0.03 * var(--shadow-opacity))),
      0 0 0 var(--control-rim-width) oklch(from var(--destructive) l c h / calc(0.18 * var(--ring-opacity))),
      0 calc(1px * var(--shadow-size)) calc(2px * var(--shadow-size))
      oklch(from var(--destructive) l c h / calc(0.1 * var(--shadow-opacity)));
  }

  .dark [data-skin="refined"] :where([data-control-family="field"][data-control="true"]),
  [data-skin="refined"].dark :where([data-control-family="field"][data-control="true"]) {
    --cui-field-border-color: oklch(from var(--border) l c h / calc(alpha * 0.5));
    --cui-field-border-width: var(--control-rim-width);
    --cui-field-shadow: none;
  }

  .dark [data-skin="refined"] :where([data-control-family="tabs"][data-slot="root"]),
  [data-skin="refined"].dark :where([data-control-family="tabs"][data-slot="root"]) {
    --cui-tabs-list-background: oklch(from var(--muted) l c h / 0.5);
    --cui-tabs-indicator-background: oklch(from var(--input) l c h / calc(alpha * 0.5));
  }
}

[data-skin="refined"][data-skin] {
  --control-fill: var(--card);
  --font-sans: var(--font-inter, "Inter"), ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-mono: var(--font-jetbrains-mono, "JetBrains Mono"), ui-monospace, SFMono-Regular, Menlo, monospace;
  --text-caption: 0.75rem;
  --text-label: 0.75rem;
  --text-body: 0.875rem;
  --text-body-lg: 0.875rem;
  --text-heading-4: 0.875rem;
  --text-heading-4--line-height: 1.5;
  --text-heading-4--font-weight: 500;
  --text-heading-3: 0.875rem;
  --text-heading-3--line-height: 1.5;
  --text-heading-3--font-weight: 500;
  --text-heading-2: 1rem;
  --text-heading-2--line-height: 1.5;
  --text-heading-2--font-weight: 500;
  --text-heading-1: 1rem;
  --text-heading-1--line-height: 1.5;
  --text-heading-1--font-weight: 500;
  --text-heading-1--letter-spacing: 0em;
  --text-display: 1rem;
  --text-display--line-height: 1.5;
  --text-display--font-weight: 500;
  --text-display--letter-spacing: 0em;

  --background: oklch(0.985 0 0);
  --foreground: oklch(0.205 0 0);
  --card: oklch(1 0 0);
  --card-foreground: var(--foreground);
  --popover: var(--card);
  --popover-foreground: var(--foreground);
  --primary: var(--foreground);
  --primary-foreground: var(--background);
  --secondary: oklch(0.95 0 0);
  --secondary-foreground: var(--foreground);
  --muted: oklch(0.96 0 0);
  --muted-foreground: oklch(0.52 0 0);
  --accent: oklch(0.955 0 0);
  --accent-foreground: var(--foreground);
  --destructive: oklch(0.55 0.2 27);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.922 0 0 / var(--ring-opacity));
  --input: oklch(0.922 0 0);
  --ring: oklch(0.5 0 0);
  --focus-ring: var(--ring);
  --primary-text: var(--foreground);
  --canvas: var(--background);

  --popover-opacity: 1;
  --backdrop-blur-popover: 0px;
  --overlay-opacity: 0.2;
  --backdrop-blur-overlay: 0px;
  --scroll-fade-size: 2rem;
  --shadow-color: oklch(0 0 0);
  --shadow-highlight: oklch(1 0 0 / 0.6);
  --shadow-size: 1;
  --shadow-opacity: 1;

  --radius: 0.625rem;
  --radius-control: var(--radius);
  --radius-field: calc(var(--radius) * 1.2);
  --radius-panel: calc(var(--radius) * 1.6);
  --radius-scene: calc(var(--radius) * 1.8);
  --radius-popup-item: calc(var(--radius) * 0.8);
  --popover-padding: 0.25rem;
  --padding-x: 0.75rem;
  --padding-y: 0.5rem;
  --control-h: 2rem;
  --control-h-xs: round(var(--control-h) * 0.75, 1px);
  --control-h-sm: round(var(--control-h) * 0.875, 1px);
  --control-h-lg: round(var(--control-h) * 1.125, 1px);

  --ease-standard: cubic-bezier(0.2, 0, 0, 1);
  --ease-emphasized: cubic-bezier(0.23, 1, 0.32, 1);
  --duration-fast: 150ms;
  --duration-base: 200ms;
  --duration-slow: 300ms;
}

.dark [data-skin="refined"][data-skin],
[data-skin="refined"][data-skin].dark {
  --background: oklch(0.17 0 0);
  --foreground: oklch(0.945 0 0);
  --card: oklch(0.205 0 0);
  --primary: oklch(0.922 0 0);
  --primary-foreground: var(--card);
  --secondary: oklch(0.269 0 0);
  --muted: oklch(0.24 0 0);
  --muted-foreground: oklch(0.7 0 0);
  --accent: oklch(0.269 0 0);
  --destructive: oklch(0.704 0.191 22.216);
  --destructive-foreground: oklch(0.17 0 0);
  --border: oklch(1 0 0 / calc(0.1 * var(--ring-opacity)));
  --input: oklch(1 0 0 / 0.15);
  --ring: oklch(0.7 0 0);
  --shadow-highlight: oklch(1 0 0 / 0.03);
}
